def _annotate(txt, notes):
	'Append each note as a `#` comment to the first line starting with its key, aligned across consecutive annotated lines.'
	ls, left, at, runs = txt.split('\n'), dict(notes), {}, []
	for i, l in enumerate(ls):
		if (k := first(left, lambda k: l.strip().startswith(k))) is not None: at[i] = left.pop(k)
	for i in at:
		if runs and runs[-1][-1] == i - 1: runs[-1].append(i)
		else: runs.append([i])
	for r in runs:
		w = max(len(ls[i]) for i in r)
		for i in r: ls[i] = f'{ls[i].ljust(w)}   # {at[i]}'
	return '\n'.join(ls)

class Caddyfile(L):
	'Build a Caddyfile that serves `domain` and forwards requests to `app:port`; each method returns a new Caddyfile.'
	def __init__(self, domain, app='app', port=5001):
		store_attr()
		super().__init__([])

	def _new(self, items):
		c = type(self)(self.domain, self.app, self.port)
		c.items = items
		return c

	def _add(self, *s): return self._new(self.items + list(s))
	def _has(self, tag): return any(t == tag for t, _ in self)
	def _get(self, tag): return L(self).filter(lambda x: x[0] == tag).itemgot(1)
	def __repr__(self): return str(self)

	def email(self, addr):
		'Set the ACME account email in the global block; Caddy also works without one.'
		return self._add(('g', f'email {addr}'))

	def acme_dns(self, provider, token_env=None):
		'Get certificates with a DNS-01 challenge through `provider`, reading its API token from the `token_env` variable.'
		token = f'{{${token_env}}}' if token_env else ''
		return self._add(('s', f'\ttls {{\n\t\tacme_dns {provider} {token}\n\t}}'))

	def cloudflared(self):
		'Serve the site over plain http:// behind a Cloudflare Tunnel, trusting the tunnel to report the client address in `Cf-Connecting-Ip`.'
		return self._add(('f', 'cloudflared'), ('g', 'servers {\n\t\ttrusted_proxies static private_ranges\n\t\tclient_ip_headers Cf-Connecting-Ip\n\t}'))

	def crowdsec(self, api_url='http://crowdsec:8080', key_env='CROWDSEC_API_KEY'):
		'Check visitors with the CrowdSec agent at `api_url`, using the key in the `key_env` variable; needs the CrowdSec plugin.'
		return self._add(('g', 'order crowdsec first'), ('g', f'crowdsec {{\n\t\tapi_url {api_url}\n\t\tapi_key {{${key_env}}}\n\t}}'), ('s', '\tcrowdsec'))

	def rate_limit(self, requests='100', window='1m'):
		'Allow each client IP address `requests` requests per `window`; needs the rate limit plugin.'
		return self._add(('s', f'\trate_limit {{\n\t\tzone dynamic {{\n\t\t\tkey {{http.request.remote_ip}}\n\t\t\tevents {requests}\n\t\t\twindow {window}\n\t\t}}\n\t}}'))

	def max_body(self, size='100m'):
		'Reject request bodies larger than `size`.'
		return self._add(('s', f'\trequest_body {{\n\t\tmax_size {size}\n\t}}'))

	def spa(self, static_dir='/app/static'):
		'Serve a single-page app from `static_dir`, falling back to index.html, instead of forwarding to the app.'
		return self._add(('spa', f'\troot * {static_dir}\n\ttry_files {{path}} /index.html\n\tfile_server'))

	def encode(self, *fmts):
		'Turn on response compression, which Caddy leaves off by default, with the encodings `fmts` in order of preference.'
		return self._add(('s', '\tencode' + ''.join(f' {f}' for f in fmts)))

	def comment(self, text):
		'Add a comment line to the site block.'
		return self._add(('s', f'\t# {text}'))

	def raw(self, block):
		'Add `block`, Caddyfile text written as it is, to the site block; its lines after the first carry their own indentation.'
		return self._add(('s', f'\t{block}'))

	def upstreams(self, ports=None, handle=False, lb_policy=None, lb_try_duration=None, lb_try_interval=None, health_uri=None,
				  health_interval=None, health_timeout=None, fail_duration=None):
		'Forward to `app` on each of `ports`, with load balancing and active health checks; `handle` wraps the proxy in a fallback `handle` block.'
		kw = dict(lb_policy=lb_policy, lb_try_duration=lb_try_duration, lb_try_interval=lb_try_interval, health_uri=health_uri,
				  health_interval=health_interval, health_timeout=health_timeout, fail_duration=fail_duration)
		return self._add(('p', (list(ports or [self.port]), {k: v for k, v in kw.items() if v is not None}, handle)))

	def notes(self, notes):
		'Write each value of `notes` as a comment after the first line that starts with its key, aligning comments on consecutive lines.'
		return self._add(('n', notes))

	def _proxy(self):
		ps, kw, hdl = first(self._get('p')) or ([self.port], {}, False)
		i = '\t\t' if hdl else '\t'
		s = f'{i}reverse_proxy ' + ' '.join(f'{self.app}:{p}' for p in ps)
		if kw: s += ' {\n' + '\n'.join(f'{i}\t{k} {v}' for k, v in kw.items()) + f'\n{i}}}'
		return f'\thandle {{\n{s}\n\t}}' if hdl else s

	def log(self, output='stderr', roll_size=None, roll_keep=None, roll_keep_for=None, format=None):
		'Turn on access logging to `output`, a Caddy log writer or a file path; `roll_*` rotate a file output.'
		if output.split()[0] not in ('stderr', 'stdout', 'discard', 'file', 'net'): output = f'file {output}'
		roll = [f'\t\t\t{k} {v}' for k,v in dict(roll_size=roll_size, roll_keep=roll_keep, roll_keep_for=roll_keep_for).items() if v is not None]
		if roll and not output.startswith('file '): raise ValueError('roll_size, roll_keep and roll_keep_for need a file output')
		body = [f'\t\toutput {output}' + (' {\n' + '\n'.join(roll) + '\n\t\t}' if roll else '')] if output != 'stderr' else []
		if format: body.append(f'\t\tformat {format}')
		return self._add(('s', '\tlog {\n' + '\n'.join(body) + '\n\t}' if body else '\tlog'))

	def __str__(self):
		'Render the Caddyfile text.'
		parts = []
		g = list(self._get('g'))
		if g: parts.append('{\n\t' + '\n\t'.join(g) + '\n}')
		prefix = 'http://' if self._has('f') else ''
		site = [f'{prefix}{self.domain} {{'] + list(self._get('s'))
		if self._has('spa'): site += list(self._get('spa'))
		else: site.append(self._proxy())
		site.append('}')
		parts.append('\n'.join(site))
		return _annotate('\n\n'.join(parts), {k: v for d in self._get('n') for k, v in d.items()}) + '\n'

	def save(self, path='Caddyfile'):
		'Write the Caddyfile to `path` and return it.'
		Path(path).write_text(str(self))
		return self

# %% ../nbs/01_proxy.ipynb #d1a11e12
def caddy(domain,  # domain to serve, such as example.com or app.example.com
          app='app',  # name of the app to forward to; in Compose, its service name
          port=5001,  # port the app listens on
          email=None,  # ACME account email, so Let's Encrypt can write to you about certificates
          dns=None,  # DNS provider for a DNS-01 challenge, such as 'cloudflare' or 'duckdns', for when port 80 is not reachable
          dns_token_env=None,  # environment variable holding the DNS provider's API token; defaults to {DNS}_API_TOKEN, such as CLOUDFLARE_API_TOKEN
          crowdsec=False,  # check visitors against a CrowdSec agent; needs a Caddy image with the CrowdSec plugin and a separate crowdsec service
          crowdsec_url='http://crowdsec:8080',  # URL of the CrowdSec agent; the default is a service called crowdsec on the same Compose network
          cloudflared=False,  # serve plain http:// behind a Cloudflare Tunnel; Caddy then fetches no certificates and dns is ignored
          encode=False,  # turn on response compression, which Caddy leaves off by default
          access_log=False  # log every request to stderr; Caddy writes no access log by default
          )->Caddyfile:
	'Build a Caddyfile that forwards `domain` to `app:port`, with optional ACME email, DNS-01 challenge, CrowdSec, tunnel mode, compression and access log.'
	cf = Caddyfile(domain, app, port)
	if email: cf = cf.email(email)
	if dns and not cloudflared: cf = cf.acme_dns(dns, dns_token_env or f'{dns.upper()}_API_TOKEN')
	if cloudflared: cf = cf.cloudflared()
	if crowdsec: cf = cf.crowdsec(api_url=crowdsec_url)
	if encode: cf = cf.encode()
	if access_log: cf = cf.log()
	return cf

def caddy_api(domain,
              app='app',
              port=5001,
              email=None,
              dns=None,
              dns_token_env=None,
              cloudflared=False,
              crowdsec=False,
              crowdsec_url='http://crowdsec:8080',
              max_body='50m',
              rate='200',
              rate_window='1m'
              ) -> str:
	'Build a `caddy` Caddyfile for an API, adding a per-IP rate limit, a cap on request bodies and compression.'
	return caddy(domain, app, port, email=email, dns=dns, dns_token_env=dns_token_env, cloudflared=cloudflared,
        crowdsec=crowdsec, crowdsec_url=crowdsec_url).rate_limit(rate, rate_window).max_body(max_body).encode()

# %% ../nbs/01_proxy.ipynb #2aaa95f8
def _caddy_img(crowdsec, cloudflare):
    if crowdsec and cloudflare: return 'ghcr.io/buildplan/csdp-caddy:latest'
    elif crowdsec: return 'serfriz/caddy-crowdsec:latest'
    elif cloudflare: return 'serfriz/caddy-cloudflare:latest'
    else: return 'caddy:2'

def caddy_svc(domain, app='app', port=5001, *, dns=None, email=None,
              crowdsec=False, cloudflared=False, conf='Caddyfile', caddyfile=None, save=True, mount=None, **kw):
    'Write the Caddyfile to `conf` and return a Caddy service for `Compose.svc`, with an image that has the plugins the options need.'
    if save: Path(conf).write_text(str(caddyfile if caddyfile is not None else caddy(domain, app, port, email=email, dns=dns, cloudflared=cloudflared, crowdsec=crowdsec)))
    is_cf = dns == 'cloudflare'
    tok = f'{dns.upper()}_API_TOKEN' if dns else None
    env = {}
    if dns: env[tok] = '${%s}' % tok
    if crowdsec: env['CROWDSEC_API_KEY'] = '${CROWDSEC_API_KEY}'
    conf_path = Path(conf)
    vol_key = mount or (str(conf_path.resolve()) if conf_path.is_absolute() else f'./{conf_path.as_posix()}')
    return service(
        image=kw.pop('image', _caddy_img(crowdsec, is_cf)),
        ports=None if cloudflared else ['80:80', '443:443', '443:443/udp'],
        env=env or None,
        volumes={vol_key: '/etc/caddy/Caddyfile', 'caddy_data': '/data', 'caddy_config': '/config'},
        depends_on=[app], networks=['web'], restart='unless-stopped', **kw
    )

# %% ../nbs/01_proxy.ipynb #52a33e28
def cloudflared_svc(token_env='${CF_TUNNEL_TOKEN}', url=None, **kw):
    'Return a Cloudflare Tunnel service for `Compose.svc`; `url` sets where the tunnel sends traffic, such as http://caddy.'
    cmd = f'tunnel --no-autoupdate run{" --url " + url if url else ""}'
    return service(image='cloudflare/cloudflared:latest', command=cmd,
                   env={'TUNNEL_TOKEN': token_env}, networks=['web'], restart='unless-stopped', **kw)

# %% ../nbs/01_proxy.ipynb #a63a6718
def crowdsec(collections=None, bouncer_key_env='CROWDSEC_BOUNCER_KEY', **kw):
    'Return a CrowdSec agent service for `Compose.svc`, with the bouncer key for Caddy read from `bouncer_key_env`.'
    cols = joins(' ', listify(collections or ['crowdsecurity/linux', 'crowdsecurity/caddy', 'crowdsecurity/http-cve']))
    return service(
        image='crowdsecurity/crowdsec:latest',
        env={'COLLECTIONS': cols, 'BOUNCER_KEY_caddy': f'${{{bouncer_key_env}}}'},
        volumes={'crowdsec-db': '/var/lib/crowdsec/data', 'crowdsec-config': '/etc/crowdsec'},
        networks=['web'], restart='unless-stopped', **kw
    )
